import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        int n = readInt(dis);
        int m = readInt(dis);
        int s = readInt(dis) - 1;
        long t = readLong(dis);

        while (t % n != 0) {
            if (s < m) {
                s = (int) ((s + t) % n);
            } else {
                s = (int) ((s - t) % n);
                if (s < 0) s += n;
            }
            t--;
        }
        t /= n;

        int[] seen = new int[n];
        Arrays.fill(seen, -1);
        seen[s] = 0;
        int count = 0;
        while (t-- > 0) {
            count++;
            int i = n - 1;
            while (i >= 1) {
                if (s < m) {
                    s = (s + i) % n;
                } else {
                    s = (s - i + n) % n;
                }
                i--;
            }
            if (seen[s] != -1) {
                t %= (count - seen[s]);
            }
            seen[s] = count;
        }
        System.out.println(s + 1);
    }

    private static int readInt(DataInputStream dis) throws IOException {
        int c = dis.read();
        while (c <= 32) c = dis.read();
        boolean negative = false;
        if (c == '-') { negative = true; c = dis.read(); }
        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = dis.read();
        }
        return negative ? -res : res;
    }

    private static long readLong(DataInputStream dis) throws IOException {
        int c = dis.read();
        while (c <= 32) c = dis.read();
        boolean negative = false;
        if (c == '-') { negative = true; c = dis.read(); }
        long res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = dis.read();
        }
        return negative ? -res : res;
    }
}
